use std::env;
use std::error::Error;
use std::fs;
use std::path::PathBuf;

use psv_vpk::icon;

const ICON_ENV: &str = "MCJAVAPSV_ICON";
const WINDOW_ICON_SIZE: u32 = 256;

/// The icon is generated by this project unless `MCJAVAPSV_ICON` names a square PNG.
/// The override is for private local builds: never commit that file or share a build made
/// with it, unless you have the rights to the artwork.
fn master() -> Result<icon::Rgba, Box<dyn Error>> {
    match env::var_os(ICON_ENV).filter(|v| !v.is_empty()) {
        None => Ok(icon::generated(WINDOW_ICON_SIZE)),
        Some(path) => {
            println!("cargo:rerun-if-changed={}", PathBuf::from(&path).display());
            let image = icon::decode_png(&fs::read(&path)?)?;
            println!("cargo:warning=using the icon from {ICON_ENV}; do not share this build");
            Ok(icon::resize(&image, WINDOW_ICON_SIZE)?)
        }
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    println!("cargo:rerun-if-env-changed={ICON_ENV}");
    println!("cargo:rerun-if-changed=build.rs");
    let out = PathBuf::from(env::var_os("OUT_DIR").ok_or("OUT_DIR is not set")?);

    let master = master()?;
    fs::write(out.join("window-icon.png"), icon::encode_png(&master)?)?;

    if env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        let ico_path = out.join("app.ico");
        fs::write(&ico_path, icon::ico_from_master(&master)?)?;

        let mut resource = winresource::WindowsResource::new();
        resource
            .set_icon(
                ico_path
                    .to_str()
                    .ok_or("the icon path is not valid UTF-8")?,
            )
            .set("ProductName", "MCJavaPSV Builder")
            .set("FileDescription", "MCJavaPSV Builder")
            .set("LegalCopyright", "MIT License");
        resource.compile()?;
    }
    Ok(())
}
